CREATE TABLE lane_why(n INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('why', 'unread')), ord INTEGER NOT NULL, value TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (n, kind, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX lane_why_value ON lane_why(kind, value);
CREATE INDEX lane_why_at ON lane_why(at);
CREATE TABLE lane_holders(n INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('slot', 'pre')), ord INTEGER NOT NULL, repo TEXT, slot TEXT, weight_from TEXT, since REAL, weight REAL, pid INTEGER, at REAL NOT NULL, PRIMARY KEY (n, kind, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX lane_holders_at ON lane_holders(at);
CREATE TABLE lane_owners(n INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('live', 'reaped')), ord INTEGER NOT NULL, repo TEXT, since REAL, slot_n INTEGER, pid INTEGER, at REAL NOT NULL, PRIMARY KEY (n, kind, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX lane_owners_at ON lane_owners(at);
CREATE TABLE miss_files(n INTEGER NOT NULL, ord INTEGER NOT NULL, value TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (n, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX miss_files_value ON miss_files(value);
CREATE INDEX miss_files_at ON miss_files(at);
CREATE TABLE reuse_windows(path TEXT NOT NULL, ord INTEGER NOT NULL, agreed INTEGER, compared INTEGER, disagreed INTEGER, flakes INTEGER, sampled INTEGER, start INTEGER, uses INTEGER, unbacked INTEGER, at REAL NOT NULL, PRIMARY KEY (path, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX reuse_windows_at ON reuse_windows(at);
CREATE TABLE reuse_evidence(path TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('now', 'was')), key TEXT, fresh TEXT, reused TEXT, fresh_from TEXT, again_fresh TEXT, again_reused TEXT, epoch INTEGER, repeated INTEGER CHECK (repeated IN (0, 1)), base TEXT, bin TEXT, checker TEXT, closure TEXT, config TEXT, corpus TEXT, entry TEXT, env TEXT, identity TEXT, field_key TEXT, node TEXT, remote TEXT, repo TEXT, rust_identity TEXT, selection TEXT, sha TEXT, step TEXT, tools TEXT, tree TEXT, at REAL NOT NULL, PRIMARY KEY (path, kind)) STRICT, WITHOUT ROWID;
CREATE TABLE request_nodes(queue TEXT NOT NULL, run TEXT NOT NULL, ord INTEGER NOT NULL, value TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (queue, run, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX request_nodes_value ON request_nodes(value);
CREATE INDEX request_nodes_at ON request_nodes(at);
CREATE TABLE request_cov_carry(queue TEXT NOT NULL, run TEXT NOT NULL, ord INTEGER NOT NULL, file TEXT, text TEXT, why TEXT, line INTEGER, own INTEGER CHECK (own IN (0, 1)), measured INTEGER CHECK (measured IN (0, 1)), at REAL NOT NULL, PRIMARY KEY (queue, run, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX request_cov_carry_at ON request_cov_carry(at);
CREATE TABLE request_cov_files(queue TEXT NOT NULL, run TEXT NOT NULL, path TEXT NOT NULL, said TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (queue, run, path)) STRICT, WITHOUT ROWID;
CREATE INDEX request_cov_files_at ON request_cov_files(at);
CREATE TRIGGER lane_starts_fill AFTER INSERT ON lane_starts WHEN NEW.rest IS NULL AND json_valid(NEW.body) BEGIN
  DELETE FROM lane_holders WHERE n = NEW.n;
  DELETE FROM lane_owners WHERE n = NEW.n;
  DELETE FROM lane_why WHERE n = NEW.n;
  UPDATE lane_starts SET declared = CASE WHEN json_type(NEW.body, '$.declared') IN ('text') THEN NEW.body ->> '$.declared' END, mode = CASE WHEN json_type(NEW.body, '$.mode') IN ('text') THEN NEW.body ->> '$.mode' END, session = CASE WHEN json_type(NEW.body, '$.session_id') IN ('text') THEN NEW.body ->> '$.session_id' END, asked_type = CASE WHEN json_type(NEW.body, '$.subagent_type') IN ('text') THEN NEW.body ->> '$.subagent_type' END, tool_use_id = CASE WHEN json_type(NEW.body, '$.tool_use_id') IN ('text') THEN NEW.body ->> '$.tool_use_id' END, verdict = CASE WHEN json_type(NEW.body, '$.verdict') IN ('text') THEN NEW.body ->> '$.verdict' END, item = CASE WHEN json_type(NEW.body, '$.item') IN ('text') THEN NEW.body ->> '$.item' END, owner = CASE WHEN json_type(NEW.body, '$.owner') IN ('text') THEN NEW.body ->> '$.owner' END, read_at = CASE WHEN json_type(NEW.body, '$.reading.at') IN ('text') THEN NEW.body ->> '$.reading.at' END, error = CASE WHEN json_type(NEW.body, '$.reading.error') IN ('text') THEN NEW.body ->> '$.reading.error' END, disk_path = CASE WHEN json_type(NEW.body, '$.reading.disk.path') IN ('text') THEN NEW.body ->> '$.reading.disk.path' END, mem_source = CASE WHEN json_type(NEW.body, '$.reading.memory.source') IN ('text') THEN NEW.body ->> '$.reading.memory.source' END, mem_low = CASE WHEN json_type(NEW.body, '$.reading.memory.low') IN ('text') THEN NEW.body ->> '$.reading.memory.low' END, slots_dir = CASE WHEN json_type(NEW.body, '$.reading.slots.dir') IN ('text') THEN NEW.body ->> '$.reading.slots.dir' END, cpu_source = CASE WHEN json_type(NEW.body, '$.reading.cpu.source') IN ('text') THEN NEW.body ->> '$.reading.cpu.source' END, pre_cap_from = CASE WHEN json_type(NEW.body, '$.reading.presteps.cap.from') IN ('text') THEN NEW.body ->> '$.reading.presteps.cap.from' END, weight_in_flight = CASE WHEN json_type(NEW.body, '$.reading.cpu_weight.in_flight') IN ('real', 'integer') THEN NEW.body ->> '$.reading.cpu_weight.in_flight' END, weight_per_core = CASE