CREATE TRIGGER reuse_audit_refill AFTER UPDATE OF body ON reuse_audit WHEN NEW.body IS NOT OLD.body AND (NEW.rest IS NULL OR NEW.rest IS OLD.rest) AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM reuse_audit WHERE path = NEW.path;
  INSERT INTO reuse_audit(path, body, at) VALUES (NEW.path, NEW.body, NEW.at);
END;
CREATE TRIGGER reuse_audit_bad AFTER UPDATE OF body ON reuse_audit WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE reuse_audit SET rest = NULL WHERE path = NEW.path;
END;
CREATE TRIGGER reuse_audit_gone AFTER DELETE ON reuse_audit BEGIN
  DELETE FROM reuse_evidence WHERE path = OLD.path;
  DELETE FROM reuse_windows WHERE path = OLD.path;
END;
