CREATE TRIGGER requests_refill AFTER UPDATE OF body ON requests WHEN NEW.body IS NOT OLD.body AND (NEW.rest IS NULL OR NEW.rest IS OLD.rest) AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM requests WHERE queue = NEW.queue AND run = NEW.run;
  INSERT INTO requests(queue, run, item, repo, sha, mode, state, pid, pid_stamp, until, filed_at, body) VALUES (NEW.queue, NEW.run, NEW.item, NEW.repo, NEW.sha, NEW.mode, NEW.state, NEW.pid, NEW.pid_stamp, NEW.until, NEW.filed_at, NEW.body);
END;
CREATE TRIGGER requests_bad AFTER UPDATE OF body ON requests WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE requests SET rest = NULL WHERE queue = NEW.queue AND run = NEW.run;
END;
CREATE TRIGGER requests_gone AFTER DELETE ON requests BEGIN
  DELETE FROM request_cov_carry WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM request_cov_files WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM request_nodes WHERE queue = OLD.queue AND run = OLD.run;
END;
CREATE TRIGGER early_fill AFTER INSERT ON early WHEN NEW.rest IS NULL AND json_valid(NEW.body) BEGIN
  DELETE FROM request_cov_carry WHERE queue = NEW.queue AND run = NEW.run;
