  INSERT INTO request_cov_files SELECT NEW.queue, NEW.run, e.key, e.value, NEW.at FROM json_each(NEW.body, '$.cov_risk.files') e WHERE (json_type(NEW.body, '$.cov_risk.files') = 'object' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.cov_risk.files') e WHERE e.type <> 'text'));
END;
CREATE TRIGGER early_refill AFTER UPDATE OF body ON early WHEN NEW.body IS NOT OLD.body AND (NEW.rest IS NULL OR NEW.rest IS OLD.rest) AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM early WHERE queue = NEW.queue AND run = NEW.run;
  INSERT INTO early(queue, run, at, body) VALUES (NEW.queue, NEW.run, NEW.at, NEW.body);
END;
CREATE TRIGGER early_bad AFTER UPDATE OF body ON early WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE early SET rest = NULL WHERE queue = NEW.queue AND run = NEW.run;
END;
CREATE TRIGGER early_gone AFTER DELETE ON early BEGIN
  DELETE FROM request_cov_carry WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM request_cov_files WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM request_nodes WHERE queue = OLD.queue AND run = OLD.run;
END;
